uniform mat4 rot_rand1; uniform mat4 rot_rand2; uniform mat4 rot_rand3; uniform mat4 rot_rand4;

float clamp01(float x) { return clamp(x, 0.0, 1.0); }
vec2 clamp01(vec2 x) { return clamp(x, vec2(0.0), vec2(1.0)); }
vec3 clamp01(vec3 x) { return clamp(x, vec3(0.0), vec3(1.0)); }
vec4 clamp01(vec4 x) { return clamp(x, vec4(0.0), vec4(1.0)); }
float lum(vec3 x) { return dot(x, vec3(0.32, 0.49, 0.29)); }
float lum(vec4 x) { return dot(x.rgb, vec3(0.32, 0.49, 0.29)); }
float sat(float x) { return clamp(x, 0.0, 1.0); }
vec2 sat(vec2 x) { return clamp(x, vec2(0.0), vec2(1.0)); }
vec3 sat(vec3 x) { return clamp(x, vec3(0.0), vec3(1.0)); }
vec4 sat(vec4 x) { return clamp(x, vec4(0.0), vec4(1.0)); }

vec3 GetPixel(vec2 uv) { return texture(sampler_main, uv).xyz; }
vec3 GetBlur1(vec2 uv) { return texture(sampler_blur1, uv).xyz; }
vec3 GetBlur2(vec2 uv) { return texture(sampler_blur2, uv).xyz; }
vec3 GetBlur3(vec2 uv) { return texture(sampler_blur3, uv).xyz; }
vec4 noise3(vec2 uv) { return texture(sampler_noise_lq, uv); }
vec3 GetMain(vec2 uv) { return texture(sampler_main, uv).xyz; }
vec2 multiply(vec2 v, mat2 m) { return m * v; }
vec3 multiply(vec3 v, mat3 m) { return m * v; }
vec4 multiply(vec4 v, mat4 m) { return m * v; }
vec4 textureBias(sampler2D s, vec4 uv4) { return textureLod(s, uv4.xy, uv4.w); }
vec4 textureLod4(sampler2D s, vec4 uv4) { return textureLod(s, uv4.xy, uv4.w); }
// Custom sampler stubs (mapped to noise texture)
#define sampler_pw_noise_lq sampler_noise_lq
#define sat clamp01
#define go   if (r2.w>0) {ret1=r2;}  if (lum(ret1)==0) {ret1=r2;}
sampler sampler_pw_noise_lq;
vec2 uv0, uv1, uv2, uv3, uv4, uv10, hh;
vec3 sky;
static vec3 fpos = vec3(q4,q5,q6);
vec3 lavcol (float t){ return clamp01(vec3(t,pow(t,2.1),pow(t, 6.0 ))) * 3.0;}
float noise (vec2 uvi) {vec2 tmp = 0; float s = 1; uvi/=8;
for (int n = 1; n <= 3; n +=1 ) {tmp += texture(sampler_noise_lq,uvi*s)/s; s*= 3;}
return tmp/1.75;}
vec3 getsky (vec2 uvi)
{ float a=GetPixel(uvi).b, b=GetBlur1(uvi).b;
b = mix(a, b, 0.0);  b = mix(GetBlur3(uvi).b,b,sat(.5+b)); b=sat(b);
return pow(b,vec3 (1.6,1.0 + b,0.7))*1.2;}
float between (float x, float hi, float lo)
{return (x<hi)*(x>lo);}
//{return sat(132.0 * (hi-x)) * sat(132.0 * (x-lo));}
float2x3 ring (vec2 uvi, float a, float b)
{ float w=.4, ra=0.04, ri=ra*0.6; float h0, h1, h2, h3; vec2 uv2;
vec3 res=0; vec3 res2=0;
uv2=multiply(uvi, mat2(cos(b),sin(b),-sin(b),cos(b)))*fpos.z;
h3 = abs(cos(a));
float sw = sin(a)*sign(cos(a));
vec2 rs=uv2;
vec2 rs0=rs;
uv2.y *= 1-.9*sat(pow(rs.y * 11.0,1.5));  //in die breite dehnen
uv2.x*=1+4*sat(2.0 * abs(rs.y)-0.05);
uv2.x*= 1-0.5*sat(pow(3.0 * (abs(rs.y)-0.055), 64.0 ));
//Seiten
rs= (uv2 + vec2(w*sign(sin(a)), 0.0 )*cos(a))* vec2(1.0 / (sin(a)), 1.0 );
res.x = between (length(rs),ra,ri);
//Zylinder, aussen
h0 = uv2.y/ra;
h1 = sqrt (1.0 - h0*h0); //schneller als h1 = cos(asin (h0));
h2 = ra*h1*sw;
res.g = between (uv2.x,w*h3+h2,-w*h3+h2)* (abs(h0)<1)*h1*h3 * 8.0;
//Zylinder, innen
h0 = uv2.y/ri;
h1 = sqrt (1.0 - h0*h0); //schneller als h1 = cos(asin (h0));
h2 = -ri*h1*sw;
res.b = between (uv2.x,w*h3+h2,-w*h3+h2)* (abs(h0)<1) * h1;
res.gb *= (res.r==0);
if (rand_preset.x>0.5) {res.b  *= (res.g==0) ;}
res2 = q7*exp(-16*length(rs0-vec2(-w*cos(a), 0.0 )))*(1.0 + res.b / 2.0)*vec3( 1.0 ,0.5,1.3); //Plasma
res2+=(res.b>0)*vec3( 1.0 ,.1,.1) * 4.0*abs(rs0.y); //Innenfluegel
//Bordlampen
h0 = length (abs(rs0)-vec2( 0.0 ,0.4));
h0 = length (vec2((rs0.x),abs(rs0.y))-vec2(-0.25*cos(a),0.4));
h1 = exp(-18*h0)* (lum(res.rg)>=0) *(1.0 + res.r * 1.0);
h2 = sat(1.0 - pow(122.0 * h0, 2.0 )) * 2.0 ;
res2 += (h1 +h2)*q9* vec3( 1.0 ,0.3,.1);
return float2x3(res,res2);
}
written by martin
END

void main() {
  vec3 ret = vec3(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  float ra=q10 / 2.0;
uv3 = multiply(uv-.5,mat2(cos(ra),sin(ra),-sin(ra),cos(ra)));
float rain = sat(texture(sampler_noise_lq, uv3*vec2 ( 1.0 ,0.02) * 2.0-4*vec2( 0.0 ,uTime / 4.0))-.6)*q28 * 0.0;
uv.x+=0.02*rain;
uv10=(uv-0.5)*uAspect.xy;
uv1=uv10+fpos.xy;
float2x3 plane = (ring (uv1,fpos.y / 2.0+1.55,1.55+q10));
vec3 pstruc = plane[0];
vec3 plight = plane[1];
float amask = lum(pstruc.g)>0;
float mask  = lum(pstruc)>0;
ret = getsky (uv);
uv2 = multiply(uv10*(1.0 - rad / 2.0)-vec2(q22,q23), mat2(cos(q21),sin(q21),-sin(q21),cos(q21)));
float flash = q24*sat (q20 * 2.0-22*length(uv2)) ;
float tt=sat (GetPixel(uv).b-GetBlur2(uv).b*0.75);
ret += flash*(4.0 * tt+ (0.001/abs(uv2.x-.1*noise(uv2+q22).r))*vec3( 1.0 ,0.5, 2.0 ));
ret *= (mask == 0.0 ? 1.0 : 0.0);
uv2 = (sin(uv*(8-8*pstruc))+vec2(2.0 * q10, 0.0 ));
ret += amask* getsky (uv2);
ret += plight ;
float zz = abs(GetPixel(uv).b-GetBlur1(uv+0.00).b);
zz= GetPixel(uv).r*0.8;
ret = max(ret,lavcol(zz)*(mask == 0.0 ? 1.0 : 0.0));
//ret += amask*lum(pstruc)*vec3( 1.0 , 1.0 , 1.0 ) / 2.0;
ret += rain*-0.15;
  fragColor = vec4(ret, 1.0);
}

